import sys
from configparser import ConfigParser
c=ConfigParser(); c['args']={}
for a in sys.argv[1:]:
    if a.startswith('--'):
        a=a[2:]
        if '=' in a:
            key,_,value=a.partition('=')
            c['args'][key]=value
        else:
            c['args'][a]=True
c.write(open('parsed.ini','w'))
print('PARSED')

